<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useAuthStore } from '@/store/auth'
import AppBackButton from '@/components/common/AppBackButton.vue'
import loyaltyApi from '@/api/loyalty.api'
import { getApiErrorMessage } from '@/api/error'
const route=useRoute(),auth=useAuthStore(), customer=ref(null), points=ref(null),wallet=ref({transactions:[]}),loading=ref(true),error=ref(''),tab=ref('profile'),editing=ref(false)
const pointForm=ref({delta:'',reason:'',idempotency_key:''}),walletForm=ref({operation:'credit',amount:'',reason:'',reference_id:''})
const canAdjust=computed(()=>auth.canAccessFinancials),fa=v=>Number(v||0).toLocaleString('fa-IR')
const visibleTabs=computed(()=>[['profile','اطلاعات'],['orders','سفارش‌ها'],['points','امتیازات'],...(canAdjust.value?[['wallet','کیف پول'],['analytics','تحلیل خرید']]:[]),['addresses','آدرس‌ها']])
async function load(){loading.value=true;error.value='';try{customer.value=await loyaltyApi.customer(route.params.customerId);points.value=await loyaltyApi.points(route.params.customerId);wallet.value=canAdjust.value?await loyaltyApi.wallet(route.params.customerId):{transactions:[]}}catch(e){error.value=getApiErrorMessage(e)}finally{loading.value=false}}
async function save(){try{customer.value=await loyaltyApi.updateCustomer(route.params.customerId,{name:customer.value.name,birthday:customer.value.birthday,notes:customer.value.notes,status:customer.value.status,marketing_sms_consent:customer.value.marketing_sms_consent,marketing_consent_source:'admin'});editing.value=false}catch(e){error.value=getApiErrorMessage(e)}}
function key(prefix){return `${prefix}-${crypto.randomUUID()}`}
async function adjustPoint(){if(!confirm('تغییر امتیاز در دفترکل ثبت شود؟'))return;try{pointForm.value.idempotency_key=key('admin');await loyaltyApi.adjustPoints(route.params.customerId,pointForm.value);pointForm.value={delta:'',reason:'',idempotency_key:''};await load()}catch(e){error.value=getApiErrorMessage(e)}}
async function adjustMoney(){if(!confirm('این عملیات مالی قطعی و قابل ممیزی است. ادامه می‌دهید؟'))return;try{walletForm.value.reference_id=key('wallet');await loyaltyApi.adjustWallet(route.params.customerId,walletForm.value);walletForm.value={operation:'credit',amount:'',reason:'',reference_id:''};await load()}catch(e){error.value=getApiErrorMessage(e)}}
onMounted(load)
</script>
<template><div class="loyalty-page"><header class="loyalty-header"><div><h1>{{customer?.name||'پروفایل مشتری'}}</h1><p v-if="customer">{{customer.phone_number}} · {{customer.membership_code}} · {{customer.tier_name||'سطح عادی'}}</p></div><AppBackButton fallback="/dashboard/loyalty/customers" /></header><p v-if="error" class="loyalty-error">{{error}}</p><p v-if="loading" class="loyalty-empty">در حال دریافت پروفایل…</p><template v-else-if="customer"><section class="loyalty-stats"><article class="loyalty-stat"><small>امتیاز فعلی</small><strong>{{fa(points?.balance)}}</strong></article><article class="loyalty-stat"><small>موجودی کیف پول</small><strong>{{fa(wallet?.balance)}}</strong></article><article class="loyalty-stat"><small>سفارش تأییدشده</small><strong>{{fa(customer.completed_orders)}}</strong></article><article class="loyalty-stat"><small>خرید تأییدشده</small><strong>{{fa(customer.verified_spend)}}</strong></article></section><nav class="loyalty-tabs"><button v-for="t in [['profile','اطلاعات'],['orders','سفارش‌ها'],['points','امتیازات'],['wallet','کیف پول'],['analytics','تحلیل خرید'],['addresses','آدرس‌ها']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></nav><section v-if="tab==='profile'" class="loyalty-card"><div class="loyalty-form"><label>نام<input v-model="customer.name" :disabled="!editing"></label><label>تولد<input v-model="customer.birthday" type="date" :disabled="!editing"></label><label>وضعیت<select v-model="customer.status" :disabled="!editing"><option value="active">فعال</option><option value="inactive">غیرفعال</option><option value="blocked">مسدود</option></select></label><label>یادداشت<textarea v-model="customer.notes" :disabled="!editing"></textarea></label><label><span>رضایت پیامک تبلیغاتی</span><input v-model="customer.marketing_sms_consent" type="checkbox" :disabled="!editing"></label><div class="loyalty-actions"><button v-if="!editing" class="admin-button admin-button--secondary" @click="editing=true">ویرایش</button><button v-else class="admin-button admin-button--primary" @click="save">ذخیره</button></div></div></section><section v-if="tab==='orders'" class="loyalty-card loyalty-table-wrap"><table class="loyalty-table"><thead><tr><th>شماره</th><th>کانال</th><th>وضعیت</th><th>مبلغ</th><th>پرداخت</th><th>تاریخ</th></tr></thead><tbody><tr v-for="o in customer.orders" :key="o.id"><td>{{o.order_number}}</td><td>{{{online:'آنلاین',in_store:'حضوری',phone:'تلفنی'}[o.order_type]}}</td><td>{{o.status}}</td><td>{{fa(o.net_cost)}}</td><td>{{o.paid?'تأییدشده':'پرداخت‌نشده'}}</td><td>{{new Date(o.created).toLocaleDateString('fa-IR')}}</td></tr><tr v-if="!customer.orders.length"><td colspan="6" class="loyalty-empty">سفارشی ثبت نشده است.</td></tr></tbody></table></section><section v-if="tab==='points'" class="loyalty-grid-2"><article class="loyalty-card loyalty-table-wrap"><h2>دفترکل امتیاز</h2><table class="loyalty-table"><thead><tr><th>تغییر</th><th>مانده</th><th>نوع</th><th>دلیل</th><th>زمان</th></tr></thead><tbody><tr v-for="t in points.transactions" :key="t.id"><td>{{t.points_delta>0?'+':''}}{{fa(t.points_delta)}}</td><td>{{fa(t.balance_after)}}</td><td>{{t.transaction_type}}</td><td>{{t.reason}}</td><td>{{new Date(t.created).toLocaleString('fa-IR')}}</td></tr></tbody></table></article><form v-if="canAdjust" class="loyalty-card loyalty-form" @submit.prevent="adjustPoint"><h2>اصلاح دستی امتیاز</h2><label>مقدار (منفی برای کسر)<input v-model.number="pointForm.delta" type="number" required></label><label>دلیل<textarea v-model="pointForm.reason" required></textarea></label><button class="admin-button admin-button--primary">ثبت با تأیید</button></form></section><section v-if="tab==='wallet'" class="loyalty-grid-2"><article class="loyalty-card loyalty-table-wrap"><h2>تراکنش‌های کیف پول</h2><table class="loyalty-table"><thead><tr><th>مبلغ</th><th>نوع</th><th>مرجع</th><th>مانده</th><th>زمان</th></tr></thead><tbody><tr v-for="t in wallet.transactions" :key="t.id"><td>{{fa(t.amount)}}</td><td>{{t.transaction_type}}</td><td>{{t.reference_id}}</td><td>{{fa(t.balance_after)}}</td><td>{{new Date(t.created_at).toLocaleString('fa-IR')}}</td></tr></tbody></table></article><form v-if="canAdjust" class="loyalty-card loyalty-form" @submit.prevent="adjustMoney"><h2>اصلاح کیف پول</h2><label>عملیات<select v-model="walletForm.operation"><option value="credit">افزایش</option><option value="debit">کاهش</option></select></label><label>مبلغ<input v-model="walletForm.amount" type="number" min="1" step="1" required></label><label>دلیل<textarea v-model="walletForm.reason" required></textarea></label><button class="admin-button admin-button--primary">ثبت عملیات مالی</button></form></section><section v-if="tab==='analytics'" class="loyalty-card"><div class="loyalty-stats"><article class="loyalty-stat"><small>آخرین خرید</small><strong>{{customer.last_purchase?new Date(customer.last_purchase).toLocaleDateString('fa-IR'):'—'}}</strong></article><article class="loyalty-stat"><small>میانگین سفارش</small><strong>{{fa(customer.completed_orders?customer.verified_spend/customer.completed_orders:0)}}</strong></article></div><h2>محصولات محبوب</h2><ul><li v-for="p in customer.favorite_products" :key="JSON.stringify(p)">{{p.items__item__name||p.items__item_option__item__name}} — {{fa(p.quantity)}} عدد</li></ul><p v-if="!customer.favorite_products.length" class="loyalty-empty">داده خرید کافی وجود ندارد.</p></section><section v-if="tab==='addresses'" class="loyalty-card"><article v-for="a in customer.addresses" :key="a.id"><h3>{{a.name}}</h3><p>{{a.detail}}</p></article><p v-if="!customer.addresses.length" class="loyalty-empty">آدرسی ذخیره نشده است.</p></section></template></div></template>
